// Tests of the gen and vectors --kind commands (docs/plans/fsm-v1/plan.md, C-5): run('gen') refuses an unknown kind, and the
// command line writes the generated set under --out, removes the stale generated files there, and refuses a file without the
// fsm-gen header (it is reported as a finding; nothing is written or removed). Every case writes into a temporary
// directory that is removed when the file's tests end.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import test, { after } from 'node:test';
import { fileURLToPath } from 'node:url';
import { run } from '../src/core/run.mjs';
import { jsonStore } from '../src/store-json/store.mjs';
import { ORDER_PROJECT } from './order-project.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '../../..');
const CLI = path.resolve(HERE, '../src/cli/fsm-gen.mjs');
const GOLDEN = path.join(HERE, 'golden/npm');
const GOLDEN_PHP = path.join(HERE, 'golden/php');
const roots = [];

/** A new temporary directory, removed when the file's tests end. */
function tempDir() {
  const root = mkdtempSync(path.join(tmpdir(), 'fsm-gen-npm-'));
  roots.push(root);
  return root;
}

/** Runs the command line of fsm-gen with `args` and returns its status, stdout and stderr. */
function gen(args) {
  const result = spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8' });
  return { status: result.status, stdout: result.stdout, stderr: result.stderr };
}

const golden = name => readFileSync(path.join(GOLDEN, name), 'utf8');
const GOLDEN_SRC = ['order.js', 'order.d.ts', 'fsm.js', 'fsm.d.ts', 'index.js', 'index.d.ts'];

after(() => {
  for (const root of roots) rmSync(root, { recursive: true, force: true });
});

test('run gen refuses an unknown kind with an Error and reads nothing', async () => {
  await assert.rejects(run('gen', jsonStore(path.join(ROOT, 'contracts')), { kind: 'ruby' }), /unknown kind ruby/);
  await assert.rejects(run('gen', jsonStore(path.join(ROOT, 'contracts')), {}), /unknown kind undefined/);
});

test('gen --kind npm writes the golden src files and exits 0 with a one-line summary', () => {
  const out = path.join(tempDir(), 'src');
  assert.deepEqual(gen(['gen', '--project', ORDER_PROJECT, '--kind', 'npm', '--out', out]), { status: 0, stdout: '[fsm-gen] gen: ok\n', stderr: '' });
  for (const name of GOLDEN_SRC) assert.equal(readFileSync(path.join(out, name), 'utf8'), golden(`src/${name}`), name);
});

test('gen removes a stale file that carries the generated header and keeps the others', () => {
  const out = path.join(tempDir(), 'src');
  mkdirSync(out, { recursive: true });
  writeFileSync(path.join(out, 'stale.js'), '// Code generated by fsm-gen from gone; DO NOT EDIT.\nexport {};\n');
  assert.equal(gen(['gen', '--project', ORDER_PROJECT, '--kind', 'npm', '--out', out]).status, 0);
  assert.equal(existsSync(path.join(out, 'stale.js')), false);
  assert.equal(readFileSync(path.join(out, 'order.js'), 'utf8'), golden('src/order.js'));
});

test('gen refuses a file without the header: a finding, exit 1, and nothing written or removed', () => {
  const out = path.join(tempDir(), 'src');
  mkdirSync(out, { recursive: true });
  writeFileSync(path.join(out, 'order.js'), 'export const hand = 1;\n');
  writeFileSync(path.join(out, 'notes.txt'), 'hand written\n');
  const result = gen(['gen', '--project', ORDER_PROJECT, '--kind', 'npm', '--out', out]);
  assert.equal(result.status, 1);
  assert.match(result.stderr, /^\[fsm-gen\] E_NOT_GENERATED - order\.js: /m);
  assert.match(result.stderr, /^\[fsm-gen\] E_NOT_GENERATED - notes\.txt: /m);
  assert.equal(readFileSync(path.join(out, 'order.js'), 'utf8'), 'export const hand = 1;\n');
  assert.equal(existsSync(path.join(out, 'fsm.js')), false);
  assert.equal(existsSync(path.join(out, 'notes.txt')), true);
});

test('gen with an unknown kind, or without --kind, is a usage error with exit 2 and writes nothing', () => {
  const out = path.join(tempDir(), 'src');
  const unknown = gen(['gen', '--project', ORDER_PROJECT, '--kind', 'ruby', '--out', out]);
  assert.equal(unknown.status, 2);
  assert.match(unknown.stderr, /usage/);
  assert.equal(gen(['gen', '--project', ORDER_PROJECT, '--out', out]).status, 2);
  assert.equal(existsSync(out), false);
});

test('vectors --kind rust refuses to overwrite a file without the header', () => {
  const file = path.join(tempDir(), 'vectors.rs');
  writeFileSync(file, 'const VECTORS: [u8; 0] = [];\n');
  const result = gen(['vectors', '--project', ORDER_PROJECT, '--kind', 'rust', '--out', file]);
  assert.equal(result.status, 1);
  assert.match(result.stderr, /^\[fsm-gen\] E_NOT_GENERATED - vectors\.rs: /m);
  assert.equal(readFileSync(file, 'utf8'), 'const VECTORS: [u8; 0] = [];\n');
});

test('vectors with an unknown kind is a usage error', () => {
  assert.equal(gen(['vectors', '--project', ORDER_PROJECT, '--kind', 'ruby', '--out', path.join(tempDir(), 'v.mjs')]).status, 2);
});

const PHP_NAMESPACE = 'Polyspec\\FsmTest';

test('gen --kind php writes the golden src tree of the order example for --php-namespace', () => {
  const out = path.join(tempDir(), 'src');
  assert.deepEqual(gen(['gen', '--project', ORDER_PROJECT, '--kind', 'php', '--php-namespace', PHP_NAMESPACE, '--out', out]), { status: 0, stdout: '[fsm-gen] gen: ok\n', stderr: '' });
  for (const name of ['Order/State.php', 'Order/Event.php', 'Order/Step.php', 'Order/functions.php', 'Fsm/Code.php', 'Fsm/Error.php']) {
    assert.equal(readFileSync(path.join(out, name), 'utf8'), readFileSync(path.join(GOLDEN_PHP, 'src', name), 'utf8'), name);
  }
});

test('gen --kind php without --php-namespace, or --php-namespace with another kind, is a usage error with exit 2', () => {
  const out = path.join(tempDir(), 'src');
  const missing = gen(['gen', '--project', ORDER_PROJECT, '--kind', 'php', '--out', out]);
  assert.equal(missing.status, 2);
  assert.match(missing.stderr, /usage: .*--php-namespace/);
  const wrongKind = gen(['gen', '--project', ORDER_PROJECT, '--kind', 'npm', '--php-namespace', PHP_NAMESPACE, '--out', out]);
  assert.equal(wrongKind.status, 2);
  assert.match(wrongKind.stderr, /--php-namespace is an option of the php and php-ext kinds/);
  const malformed = gen(['gen', '--project', ORDER_PROJECT, '--kind', 'php', '--php-namespace', 'Bad Name', '--out', out]);
  assert.equal(malformed.status, 2);
  assert.equal(existsSync(out), false);
});

test('gen --kind php recognizes the header after <?php and the blank line of PSR-12: a stale generated file goes, a hand-written one is refused', () => {
  const out = path.join(tempDir(), 'src');
  mkdirSync(path.join(out, 'Order'), { recursive: true });
  writeFileSync(path.join(out, 'Order', 'Stale.php'), '<?php\n\n// Code generated by fsm-gen from gone; DO NOT EDIT.\n');
  assert.equal(gen(['gen', '--project', ORDER_PROJECT, '--kind', 'php', '--php-namespace', PHP_NAMESPACE, '--out', out]).status, 0);
  assert.equal(existsSync(path.join(out, 'Order', 'Stale.php')), false);
  writeFileSync(path.join(out, 'Order', 'Hand.php'), '<?php\n\n// hand written\n');
  const refused = gen(['gen', '--project', ORDER_PROJECT, '--kind', 'php', '--php-namespace', PHP_NAMESPACE, '--out', out]);
  assert.equal(refused.status, 1);
  assert.match(refused.stderr, /^\[fsm-gen\] E_NOT_GENERATED - Order\/Hand\.php: /m);
  assert.equal(readFileSync(path.join(out, 'Order', 'Hand.php'), 'utf8'), '<?php\n\n// hand written\n');
});

test('vectors --kind php writes the golden tests/ConformanceTest.php for --php-namespace', () => {
  const file = path.join(tempDir(), 'tests', 'ConformanceTest.php');
  assert.deepEqual(gen(['vectors', '--project', ORDER_PROJECT, '--kind', 'php', '--php-namespace', PHP_NAMESPACE, '--out', file]), { status: 0, stdout: '[fsm-gen] vectors: ok\n', stderr: '' });
  assert.equal(readFileSync(file, 'utf8'), readFileSync(path.join(GOLDEN_PHP, 'ConformanceTest.php'), 'utf8'));
});

test('vectors --kind php without --php-namespace is a usage error with exit 2', () => {
  assert.equal(gen(['vectors', '--project', ORDER_PROJECT, '--kind', 'php', '--out', path.join(tempDir(), 'ConformanceTest.php')]).status, 2);
});
